package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"bind_address", "listen_address", "ip_address", "host", "server_address", "endpoint", "network_interface", "public_ip", "private_ip", "ingress_rules", "security_group", "expose", "publicly_accessible", "external_ip", "port_forwarding"}

    attr.value.ir_type == "String"
    attr.value.value in {"0.0.0.0", "::0"}

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Binding to an Unrestricted IP Address - Services should not bind to 0.0.0.0 or ::0 without proper IP restrictions. (CWE-1327)"
    }
}

