package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Variables within the parent UnitBlock
    variable := parent.variables[_]
    check_value(variable.value)

    result := {
        "type": "sec_invalid_bind",
        "element": variable,
        "path": parent.path,
        "description": "Binding to an Unrestricted IP Address - Services should not bind to 0.0.0.0 without specific restrictions. (CWE-1327)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check Attributes within the parent UnitBlock
    attribute := parent.attributes[_]
    check_value(attribute.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attribute,
        "path": parent.path,
        "description": "Binding to an Unrestricted IP Address - Services should not bind to 0.0.0.0 without specific restrictions. (CWE-1327)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes recursively in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    check_value(attr.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Binding to an Unrestricted IP Address - Services should not bind to 0.0.0.0 without specific restrictions. (CWE-1327)"
    }
}

check_value(val) {
    val.ir_type == "String"
    regex.match("^(0\.0\.0\.0|::0)$", val.value)
} else {
    val.ir_type == "Hash"
    check_hash(val.value)
}

check_hash(pairs) {
    pair := pairs[_]
    check_value(pair.value)
}

